"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

from dataclasses import dataclass


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __lt__(self, other: Version) -> bool:
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        # Prerelease comparison
        if bool(self.prerelease) != bool(other.prerelease):
            return bool(self.prerelease)  # version with prerelease < version without

        if self.prerelease and other.prerelease:
            return self._compare_prerelease(self.prerelease, other.prerelease) < 0

        return False

    def __le__(self, other: Version) -> bool:
        return self < other or self == other

    def __gt__(self, other: Version) -> bool:
        return other < self

    def __ge__(self, other: Version) -> bool:
        return other <= self

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        # Build metadata is ignored
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    @staticmethod
    def _compare_prerelease(pre1: tuple[str, ...], pre2: tuple[str, ...]) -> int:
        for i in range(min(len(pre1), len(pre2))):
            p1, p2 = pre1[i], pre2[i]
            is_digit1 = p1.isdigit()
            is_digit2 = p2.isdigit()

            if is_digit1 and is_digit2:
                if int(p1) != int(p2):
                    return int(p1) - int(p2)
            elif is_digit1:
                return -1  # digit < non-digit
            elif is_digit2:
                return 1  # non-digit > digit
            else:
                if p1 != p2:
                    return -1 if p1 < p2 else 1

        if len(pre1) != len(pre2):
            return len(pre1) - len(pre2)
        return 0


def parse_version(s: str) -> Version:
    """Parse a version string into a Version object. Raise RangeError if malformed."""
    if not s or s != s.strip() or s.startswith('v'):
        raise RangeError(f"Invalid version: {s}")

    # Split build metadata
    if '+' in s:
        version_part, build_part = s.rsplit('+', 1)
        build = tuple(build_part.split('.'))
        if not build or any(not b for b in build):
            raise RangeError(f"Invalid version: {s}")
    else:
        version_part = s
        build = ()

    # Split prerelease
    if '-' in version_part:
        version_nums, prerelease_part = version_part.split('-', 1)
        prerelease = tuple(prerelease_part.split('.'))
        if not prerelease or any(not p for p in prerelease):
            raise RangeError(f"Invalid version: {s}")
        for p in prerelease:
            if not all(c in '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-' for c in p):
                raise RangeError(f"Invalid version: {s}")
            if p.isdigit() and len(p) > 1 and p[0] == '0':
                raise RangeError(f"Invalid version: {s}")
    else:
        version_nums = version_part
        prerelease = ()

    # Parse major.minor.patch
    parts = version_nums.split('.')
    if len(parts) != 3:
        raise RangeError(f"Invalid version: {s}")

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError:
        raise RangeError(f"Invalid version: {s}")

    # Check for leading zeros
    for p in parts:
        if len(p) > 1 and p[0] == '0':
            raise RangeError(f"Invalid version: {s}")

    if major < 0 or minor < 0 or patch < 0:
        raise RangeError(f"Invalid version: {s}")

    return Version(major, minor, patch, prerelease, build)


@dataclass(frozen=True)
class Comparator:
    op: str  # '=', '>', '>=', '<', '<='
    version: Version


@dataclass(frozen=True)
class ComparatorSet:
    comparators: tuple[Comparator, ...]


def parse_partial_version(s: str) -> tuple[int, ...]:
    """Parse a partial version (may have x/X/*/or fewer components)."""
    parts = s.split('.')
    result = []

    for i, part in enumerate(parts):
        if i >= 3:
            raise RangeError(f"Too many version components: {s}")

        if part in ('x', 'X', '*'):
            # Wildcards make everything to the right a wildcard
            if i < len(parts) - 1:
                for j in range(i+1, len(parts)):
                    if parts[j] not in ('x', 'X', '*'):
                        raise RangeError(f"Non-wildcard after wildcard: {s}")
            # This signals partial - return what we have so far
            return tuple(result)

        if not part.isdigit():
            raise RangeError(f"Invalid version component: {part}")

        num = int(part)
        if len(part) > 1 and part[0] == '0':
            raise RangeError(f"Leading zero in version: {s}")
        result.append(num)

    return tuple(result)


def desugared_range(spec: str) -> list[Comparator]:
    """Convert a spec (like ^1.2.3 or 1.2.x) to primitive comparators."""
    spec = spec.strip()

    if not spec or spec in ('*', 'x', 'X'):
        return [Comparator('>=', Version(0, 0, 0))]

    if spec.startswith('^'):
        return _parse_caret(spec[1:])
    elif spec.startswith('~'):
        return _parse_tilde(spec[1:])
    elif spec.startswith('>=') or spec.startswith('<=') or spec.startswith('!='):
        op = spec[:2]
        version_str = spec[2:].strip()
        if not version_str:
            raise RangeError(f"Missing version after {op}")
        v = parse_version(version_str)
        return [Comparator(op, v)]
    elif spec.startswith('>') or spec.startswith('<') or spec.startswith('='):
        op = spec[0]
        version_str = spec[1:].strip()
        if not version_str:
            raise RangeError(f"Missing version after {op}")
        v = parse_version(version_str)
        return [Comparator(op, v)]
    else:
        # Bare version (possibly partial)
        if not all(c in '0123456789.xX*' for c in spec):
            raise RangeError(f"Invalid version spec: {spec}")

        parts = parse_partial_version(spec)

        if len(parts) == 3:
            # Fully specified
            v = Version(parts[0], parts[1], parts[2])
            return [Comparator('=', v)]
        elif len(parts) == 2:
            # 1.2 -> >=1.2.0 <1.3.0
            lower = Version(parts[0], parts[1], 0)
            upper = Version(parts[0], parts[1] + 1, 0)
            return [Comparator('>=', lower), Comparator('<', upper)]
        elif len(parts) == 1:
            # 1 -> >=1.0.0 <2.0.0
            lower = Version(parts[0], 0, 0)
            upper = Version(parts[0] + 1, 0, 0)
            return [Comparator('>=', lower), Comparator('<', upper)]
        else:
            raise RangeError(f"Invalid partial version: {spec}")


def _parse_caret(spec: str) -> list[Comparator]:
    """Parse ^... into comparators."""
    spec = spec.strip()
    if not spec or spec in ('*', 'x', 'X'):
        raise RangeError(f"^* or ^x is malformed")

    # Check if it's fully specified (has prerelease/build)
    has_prerelease_or_build = '-' in spec or '+' in spec
    if has_prerelease_or_build:
        # Must be fully specified version
        lower = parse_version(spec)
        parts = (lower.major, lower.minor, lower.patch)
        major, minor, patch = parts
    else:
        parts = parse_partial_version(spec)

        if len(parts) == 0:
            raise RangeError(f"Caret needs at least major: {spec}")

        # Lower bound
        if len(parts) == 1:
            lower = Version(parts[0], 0, 0)
            major, minor, patch = parts[0], 0, 0
        elif len(parts) == 2:
            lower = Version(parts[0], parts[1], 0)
            major, minor, patch = parts[0], parts[1], 0
        else:  # len(parts) == 3
            lower = Version(parts[0], parts[1], parts[2])
            major, minor, patch = parts[0], parts[1], parts[2]

    # Find leftmost non-zero or last specified
    if major != 0:
        increment_idx = 0
    elif minor != 0:
        increment_idx = 1
    else:
        increment_idx = len(parts) - 1

    if increment_idx == 0:
        upper = Version(major + 1, 0, 0)
    elif increment_idx == 1:
        upper = Version(major, minor + 1, 0)
    else:  # increment_idx == 2
        upper = Version(major, minor, patch + 1)

    return [Comparator('>=', lower), Comparator('<', upper)]


def _parse_tilde(spec: str) -> list[Comparator]:
    """Parse ~... into comparators."""
    spec = spec.strip()
    if not spec or spec in ('*', 'x', 'X'):
        raise RangeError(f"~* or ~x is malformed")

    # Check if it's fully specified (has prerelease/build)
    has_prerelease_or_build = '-' in spec or '+' in spec
    if has_prerelease_or_build:
        # Must be fully specified version
        lower = parse_version(spec)
        major, minor = lower.major, lower.minor
        parts = (lower.major, lower.minor, lower.patch)
        has_minor = True
    else:
        parts = parse_partial_version(spec)

        if len(parts) == 0:
            raise RangeError(f"Tilde needs at least major: {spec}")

        # Lower bound
        if len(parts) == 1:
            lower = Version(parts[0], 0, 0)
            major = parts[0]
            has_minor = False
        elif len(parts) == 2:
            lower = Version(parts[0], parts[1], 0)
            major, minor = parts[0], parts[1]
            has_minor = True
        else:  # len(parts) == 3
            lower = Version(parts[0], parts[1], parts[2])
            major, minor = parts[0], parts[1]
            has_minor = True

    # Upper bound
    if has_minor:
        upper = Version(major, minor + 1, 0)
    else:
        upper = Version(major + 1, 0, 0)

    return [Comparator('>=', lower), Comparator('<', upper)]


def parse_range_expr(expr: str) -> list[ComparatorSet]:
    """Parse a range expression into comparator sets."""
    expr = expr.strip()

    if not expr:
        # Empty expression matches everything
        return [ComparatorSet((Comparator('>=', Version(0, 0, 0)),))]

    # Split by ||
    sets = expr.split('||')
    result = []

    for s in sets:
        s = s.strip()
        if not s:
            raise RangeError("Empty comparator set")

        # Parse comparator set
        tokens = s.split()

        # Check for hyphen range: A - B
        if '-' in tokens:
            if tokens.count('-') != 1:
                raise RangeError("Multiple hyphens in range")
            idx = tokens.index('-')

            if idx == 0 or idx == len(tokens) - 1:
                raise RangeError("Hyphen range missing operand")

            # Must be exactly 3 tokens
            if len(tokens) != 3:
                raise RangeError("Hyphen range must be exactly 'A - B'")

            a_str = tokens[0]
            b_str = tokens[2]

            # Both need at least major
            a_parts = parse_partial_version(a_str)
            b_parts = parse_partial_version(b_str)

            if len(a_parts) == 0 or len(b_parts) == 0:
                raise RangeError("Hyphen range operands need at least major")

            # Lower bound: >=A (completed with zeros, keeping prerelease)
            if '+' in a_str or '-' in a_str.split('+')[0]:
                a_ver = parse_version(a_str)
            else:
                a_ver = Version(a_parts[0],
                               a_parts[1] if len(a_parts) > 1 else 0,
                               a_parts[2] if len(a_parts) > 2 else 0)

            # Upper bound
            if len(b_parts) == 3:
                # Fully specified: <=B
                b_ver = parse_version(b_str)
                comparators = [Comparator('>=', a_ver), Comparator('<=', b_ver)]
            else:
                # Partial: <B (incremented)
                if len(b_parts) == 1:
                    b_upper = Version(b_parts[0] + 1, 0, 0)
                else:  # len(b_parts) == 2
                    b_upper = Version(b_parts[0], b_parts[1] + 1, 0)
                comparators = [Comparator('>=', a_ver), Comparator('<', b_upper)]

            result.append(ComparatorSet(tuple(comparators)))
        else:
            # Regular comparators
            if len(tokens) == 0:
                raise RangeError("Empty comparator set")

            comparators = []
            i = 0
            while i < len(tokens):
                token = tokens[i]

                # Check if operator is attached to version (like >=1.2.3)
                if token.startswith('>=') or token.startswith('<=') or token.startswith('!='):
                    op = token[:2]
                    version_str = token[2:]
                    if not version_str:
                        raise RangeError(f"Missing version after {op}")
                    v = parse_version(version_str)
                    comparators.append(Comparator(op, v))
                    i += 1
                elif token.startswith('>') or token.startswith('<') or token.startswith('='):
                    op = token[0]
                    version_str = token[1:]
                    if not version_str:
                        raise RangeError(f"Missing version after {op}")
                    v = parse_version(version_str)
                    comparators.append(Comparator(op, v))
                    i += 1
                # Try to parse as range spec
                elif token.startswith('^') or token.startswith('~'):
                    cmp_list = desugared_range(token)
                    comparators.extend(cmp_list)
                    i += 1
                elif token in ('*', 'x', 'X', '') or (token and token[0] in '0123456789'):
                    cmp_list = desugared_range(token)
                    comparators.extend(cmp_list)
                    i += 1
                elif token in ('=', '>', '<', '>=', '<='):
                    if i + 1 >= len(tokens):
                        raise RangeError(f"Missing version after {token}")
                    version_str = tokens[i + 1]
                    v = parse_version(version_str)
                    comparators.append(Comparator(token, v))
                    i += 2
                else:
                    raise RangeError(f"Invalid comparator: {token}")

            if not comparators:
                raise RangeError("No comparators in set")

            result.append(ComparatorSet(tuple(comparators)))

    if not result:
        raise RangeError("Empty range expression")

    return result


def version_satisfies_comparator_set(version: Version, comp_set: ComparatorSet) -> bool:
    """Check if a version satisfies all comparators in a set."""
    # Check if version satisfies all comparators
    for comp in comp_set.comparators:
        if not version_satisfies_comparator(version, comp):
            return False

    # Prerelease rule: if version has prerelease, at least one comparator
    # must have prerelease and same major.minor.patch
    if version.prerelease:
        has_matching_prerelease = False
        for comp in comp_set.comparators:
            if (comp.version.prerelease and
                comp.version.major == version.major and
                comp.version.minor == version.minor and
                comp.version.patch == version.patch):
                has_matching_prerelease = True
                break

        if not has_matching_prerelease:
            return False

    return True


def version_satisfies_comparator(version: Version, comp: Comparator) -> bool:
    """Check if a version satisfies a single comparator."""
    if comp.op == '=':
        return version == comp.version
    elif comp.op == '>':
        return version > comp.version
    elif comp.op == '>=':
        return version >= comp.version
    elif comp.op == '<':
        return version < comp.version
    elif comp.op == '<=':
        return version <= comp.version
    else:
        raise RangeError(f"Unknown operator: {comp.op}")


def version_satisfies_range(version: Version, comp_sets: list[ComparatorSet]) -> bool:
    """Check if a version satisfies at least one comparator set (OR logic)."""
    for comp_set in comp_sets:
        if version_satisfies_comparator_set(version, comp_set):
            return True
    return False


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    # Parse all versions first (validates them)
    parsed = []
    for v_str in versions:
        parsed.append((v_str, parse_version(v_str)))

    # Parse range
    comp_sets = parse_range_expr(range_expr)

    # Find satisfying versions
    satisfying = []
    for v_str, v_parsed in parsed:
        if version_satisfies_range(v_parsed, comp_sets):
            satisfying.append((v_str, v_parsed))

    if not satisfying:
        return None

    # Find the highest precedence version, with ties going to the earliest in the list
    max_version = satisfying[0][1]
    max_idx = 0

    for i, (v_str, v_parsed) in enumerate(satisfying[1:], 1):
        if v_parsed > max_version:
            max_version = v_parsed
            max_idx = i

    return satisfying[max_idx][0]
